import json,collections,statistics as s
q=collections.defaultdict(int); lat={}
rows=[json.loads(l) for l in open('app.log') if l.startswith('{')]
for r in rows:
    if r['service']!='checkout': continue
    m=r['msg']
    if 'order_items WHERE' in m: q[r.get('request_id')]+=1
    if m.startswith('request_end') and 'summary' in m: lat[r['request_id']]=(r['ts'],r['latency_ms'],r['status'])
print(len(q), 'req with n+1; sample counts', sorted(q.values())[:3], sorted(q.values())[-3:])
for lo,hi in [('14:00','14:06'),('14:06','14:18'),('14:18','14:29'),('14:29','14:38'),('14:38','15:00')]:
    v=[l for t,l,st in lat.values() if lo<=t[11:16]<hi]
    print(lo,hi,len(v),int(s.median(v)) if v else None,max(v) if v else None)
print(collections.Counter(r['msg'][:40] for r in rows if r['service']=='checkout' and 'cache' in r['msg']).most_common(5))
print([ (r['ts'],r['msg']) for r in rows if r['service']=='checkout' and r['ts'][11:16] in('14:28','14:29') and 'summary' in r['msg']][:6])
E"
